// ── #1059: an UNENFORCEABLE grant scope refuses, it does not fail open ──────
//
// `--allow-read=/anything` used to parse to the bare `read` grant: the suffix
// was dropped on the floor and the program got BLANKET read, exit 0, stderr
// empty. The narrower-looking spelling bought the WIDER authority — the
// #713/#880 fail-open-silence class in the one direction a deny-by-default
// system must never be silent in. It now refuses at startup (exit 2), before
// any evaluation.

// The report's own four probe rows. Every one of them read /etc/hosts at
// v0.16.0; every one of them must now refuse without running the program.
fn test_issue_1059_read_scope_suffix_refuses_at_startup() {
	prog := tmp_file_run('prog_1059_rd', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	for suffix in ['/tmp', '/nonexistent', 'garbage', ''] {
		r := os.execute('${cx_bin()} --allow-read=${suffix} ${prog} 2>&1')
		assert r.exit_code == 2, '--allow-read=${suffix} must exit 2, got ${r.exit_code}: ${r.output}'
		assert r.output.contains('--allow-read=${suffix}'), 'diagnostic must name the flag AS TYPED: ${r.output}'
		assert r.output.contains('NOT IMPLEMENTED'), 'diagnostic must say scoping is unimplemented: ${r.output}'
		assert r.output.contains('--allow-read'), 'diagnostic must name the accepted bare spelling: ${r.output}'
		assert r.output.contains('1061'), 'diagnostic must name the scoping-design issue: ${r.output}'
		// Nothing evaluated: the refusal precedes the program.
		assert !r.output.contains('3'), 'the program must not run under a refused grant: ${r.output}'
	}
}

fn test_issue_1059_write_and_env_scope_suffixes_refuse() {
	prog := tmp_file_run('prog_1059_wr', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	for flag in ['--allow-write=/nonexistent', '--allow-env=HOME'] {
		r := os.execute('${cx_bin()} ${flag} ${prog} 2>&1')
		assert r.exit_code == 2, '${flag} must exit 2, got ${r.exit_code}: ${r.output}'
		assert r.output.contains(flag), 'diagnostic must name the flag: ${r.output}'
		assert r.output.contains('NOT IMPLEMENTED'), 'diagnostic must say scoping is unimplemented: ${r.output}'
		assert !r.output.contains('3'), 'the program must not run under a refused grant: ${r.output}'
	}
}

// The refusal is a REFUSAL, not a warning: it must be on stderr and the run
// must produce no stdout. (The pre-fix binary had the inverse — stdout with
// the program's result, stderr EMPTY.)
fn test_issue_1059_refusal_is_on_stderr_and_stdout_is_empty() {
	prog := tmp_file_run('prog_1059_fd', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	out := os.execute('${cx_bin()} --allow-read=/tmp ${prog} 2>/dev/null')
	assert out.output.trim_space() == '', 'a refused grant must write NOTHING to stdout: ${out.output}'
	err := os.execute('${cx_bin()} --allow-read=/tmp ${prog} 2>&1 1>/dev/null')
	assert err.output.contains('--allow-read=/tmp'), 'the refusal must be on stderr: ${err.output}'
}

// The BARE grants are untouched — this change refuses a spelling, it does not
// narrow any authority.
fn test_issue_1059_bare_grants_still_grant() {
	prog := tmp_file_run('prog_1059_bare', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	for flag in ['--allow-read', '--allow-write', '--allow-env'] {
		r := os.execute('${cx_bin()} ${flag} ${prog} 2>&1')
		assert r.exit_code == 0, '${flag} (bare) must still be accepted, got ${r.exit_code}: ${r.output}'
		assert r.output.contains('3'), 'the program must still run under a bare grant: ${r.output}'
	}
}

// --allow-net's scoping is the one that IS enforced, and it is untouched:
// the suffix is still accepted, and it still NARROWS.
fn test_issue_1059_net_scope_still_accepted_and_still_narrows() {
	prog := tmp_file_run('prog_1059_net', "[?lib 'cx-stdlib/http']\n[\$http:get 'http://127.0.0.1:9/health']\n")
	defer { os.rm(prog) or {} }
	// accepted: a matching scope reaches the DIAL (a connection error, not a
	// capability denial).
	ok := os.execute('${cx_bin()} --allow-net=127.0.0.1:9 ${prog} 2>&1')
	assert !ok.output.contains('CXER0271'), 'a matching net scope must not be capability-denied: ${ok.output}'
	// narrows: a non-matching scope is DENIED at the effect point.
	no := os.execute('${cx_bin()} --allow-net=other.test:80 ${prog} 2>&1')
	assert no.output.contains('CXER0271'), 'a non-matching net scope must deny: ${no.output}'
}

// The refusal covers every CLI grant parse site, not just the run surface —
// `cx eval` shared the identical fail-open.
fn test_issue_1059_eval_surface_refuses_too() {
	prog := tmp_file_run('prog_1059_ev', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin()} eval --allow-read=/tmp ${prog} 2>&1')
	assert r.exit_code == 2, 'cx eval must refuse a read scope, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('--allow-read=/tmp'), 'diagnostic must name the flag: ${r.output}'
	assert !r.output.contains('3'), 'cx eval must not run the program: ${r.output}'
}

// …and the remaining three CLI grant parse sites — the issue's own argument
// is that a fail-open surviving on a secondary surface is the failure mode,
// so every command word that parses --allow-* carries a pin, not just run/eval.
fn test_issue_1059_diagram_and_daemon_surfaces_refuse_too() {
	prog := tmp_file_run('prog_1059_dg', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	for cmdline in ['diagram --allow-read=/tmp ${prog}', 'store-serve --allow-read=/tmp',
		'fabric-serve --allow-write=/tmp'] {
		r := os.execute('${cx_bin()} ${cmdline} 2>&1')
		assert r.exit_code == 2, 'cx ${cmdline} must refuse the scope suffix (exit 2), got ${r.exit_code}: ${r.output}'
		assert r.output.contains('NOT IMPLEMENTED'), 'diagnostic must say scoping is unimplemented: ${r.output}'
	}
}

// Capabilities NOT in the refuse set keep their current handling — this change
// does not silently widen into a general "no suffix anywhere" rule (the
// remaining ones are recorded on #1061 §6).
fn test_issue_1059_unlisted_caps_keep_current_handling() {
	prog := tmp_file_run('prog_1059_other', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin()} --allow-clock=whenever ${prog} 2>&1')
	assert r.exit_code == 0, '--allow-clock=… is outside the #1059 refuse set, got ${r.exit_code}: ${r.output}'
}

// A value-carrying flag given without its value is a usage error.
fn test_bare_data_flag_needs_value() {
	prog := tmp_file_run('prog_val', '[+ 1 2]\n')
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin()} --data ${prog} 2>&1')
	assert r.exit_code == 2, 'bare --data must exit 2, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('--data'), 'diagnostic must name the flag: ${r.output}'
}

// PYE-2 REVERSAL of the old "extra positional is a usage error" rule: a
// second positional after the FILE is now the program's FIRST ARGUMENT.
// The old `unexpected extra argument` refusal is gone from the surface.
fn test_second_positional_is_a_program_argument() {
	prog := tmp_file_run('prog_a', '[+ 1 2]\n')
	prog2 := tmp_file_run('prog_b', '[+ 3 4]\n')
	defer {
		os.rm(prog) or {}
		os.rm(prog2) or {}
	}
