// ── 8. `cx version` is a verb, never a ./VERSION file evaluation (#426b) ─────

fn test_version_subcommand_matches_version_flag() {
	flag := os.execute('${cx_bin()} --version')
	assert flag.exit_code == 0, '--version must exit 0: ${flag.output}'
	verb := os.execute('${cx_bin()} version')
	assert verb.exit_code == 0, 'cx version must exit 0: ${verb.output}'
	assert verb.output == flag.output, 'cx version must print exactly what --version prints:\n${verb.output}\nvs\n${flag.output}'
	assert verb.output.starts_with('cx v'), 'version banner missing: ${verb.output}'
}

fn test_version_subcommand_wins_over_version_file() {
	// Repro (#426 item b): at the repo root on a case-insensitive filesystem,
	// bare `cx version` used to resolve the word to ./VERSION and evaluate
	// the file as a program. The verb must dispatch BEFORE any positional
	// file resolution — run from a directory containing a VERSION file.
	dir := os.join_path(os.temp_dir(), 'cx_version_shadow_${os.getpid()}')
	os.mkdir_all(dir) or { panic(err) }
	defer { os.rmdir_all(dir) or {} }
	os.write_file(os.join_path(dir, 'VERSION'), '0.0.0-shadow\n') or { panic(err) }
	r := os.execute('cd ${dir} && ${cx_bin()} version')
	assert r.exit_code == 0, 'cx version next to a VERSION file must exit 0: ${r.output}'
	assert r.output.starts_with('cx v'), 'version banner missing: ${r.output}'
	assert !r.output.contains('0.0.0-shadow'), './VERSION file was evaluated instead of the verb: ${r.output}'
}

// ── 8b. RULED: CO-4 (#979) — the headline is a PROVENANCE claim ─────────────
//
// The first line of `cx --version` used to be `cx v` + the VERSION file,
// unconditionally: a claim about a FILE, not about the artifact. VERSION flips
// to the NEXT version when a line's development starts, so every build between
// two cuts wore the coming release's name and nothing said otherwise —
// downstream BOMs pin on this line. Release-ness now DERIVES from git state at
// build time (HEAD exactly at the annotated tag matching VERSION, and a clean
// tree); everything else stamps `-dev+<commit>`, a semver PRE-RELEASE of
// VERSION, which is what unreleased source is and which orders BEFORE the
// release it will become.
//
// The derivation has ONE implementation (vcx/Makefile's CX_RELEASE) and the
// release state cannot be reached from CI, which never builds at a tag — so
// the contract is pinned from both ends: the pure formatter is exercised for
// BOTH define values, and the shipped binary is held to the state the Makefile
// derives for THIS tree.

fn test_version_headline_formats_both_release_states() {
	// The two ruled shapes.
	assert cli.version_headline('0.17.0', 'release', '3ed9ade5') == 'cx v0.17.0'
	assert cli.version_headline('0.17.0', 'dev', '3ed9ade5') == 'cx v0.17.0-dev+3ed9ade5'
	// #666's -dirty marker rides into the build metadata: a stamp naming a
	// commit that does not reproduce the artifact is unfalsifiable in the
	// headline for exactly the reason it is on the `commit` line.
	assert cli.version_headline('0.17.0', 'dev', '3ed9ade5-dirty') == 'cx v0.17.0-dev+3ed9ade5-dirty'
	// ONLY the exact `release` state claims a release. An unstamped build
	// (`v run cmd/` carries the `dev` default), a typo, or some future state
	// falls to the honest shape — the safe direction is the default one.
	for state in ['', 'dev', 'Release', 'RELEASE', 'released', 'true', '1'] {
		assert cli.version_headline('0.17.0', state, 'abc1234') == 'cx v0.17.0-dev+abc1234',
			'state ${state} must not claim a release'
	}
	// A build with no git identity at all still produces a well-formed
	// pre-release rather than an empty `+` metadata field.
	assert cli.version_headline('0.17.0', 'dev', '') == 'cx v0.17.0-dev+unknown'
	assert cli.version_headline('0.17.0', 'dev', '   ') == 'cx v0.17.0-dev+unknown'
	// The version number itself is never touched — it is the VERSION file.
	assert cli.version_headline('1.2.3-rc1', 'release', 'abc1234') == 'cx v1.2.3-rc1'
}

// makefile_var asks the ONE implementation of a derived build value what it
// resolves to for this tree. Returns `none` when make cannot be consulted at
// all — off a checkout, or without the Makefile — so callers skip rather than
// guess. --no-print-directory: `make -C` otherwise brackets the value with
// Entering/Leaving lines, and the value is what we came for.
fn makefile_var(name string) ?string {
	if !os.is_file(os.join_path(@VMODROOT, 'Makefile')) {
		return none
	}
	r := os.execute('make -s --no-print-directory -C ${os.quoted_path(@VMODROOT)} print-${name} 2>/dev/null')
	if r.exit_code != 0 {
		return none
	}
	lines := r.output.split_into_lines().map(it.trim_space())
	if lines.len == 0 {
		return none
	}
	// The value may legitimately be EMPTY (CX_DIRTY on a clean tree), so the
	// blank-filtering the release probe can afford is wrong here: take the
	// last line make emitted, whatever it is.
	mut last := ''
	for l in lines {
		last = l
	}
	return last
}

// makefile_release_state asks the ONE implementation of the rule which state
// it derives for this tree ('' when make cannot be consulted). Re-deriving it
// here with a second git probe would be a second source of truth — the thing
// CO-4 exists to prevent.
fn makefile_release_state() string {
	last := makefile_var('CX_RELEASE') or { return '' }
	// Anything that is not one of the two known states means the probe picked
	// up noise rather than the value — report "unknown" (skip), never a guess.
	return if last in ['release', 'dev'] { last } else { '' }
}

fn test_version_headline_never_claims_an_uncut_release() {
	version_file := os.join_path(os.dir(@VMODROOT), 'VERSION')
	raw := os.read_file(version_file) or {
		assert false, 'cannot read the repo-root VERSION file at ${version_file}: ${err}'
		return
	}
	ver := raw.trim_space()

	r := os.execute('${cx_bin()} --version')
	assert r.exit_code == 0, '--version must exit 0: ${r.output}'
	lines := r.output.split_into_lines()
	assert lines.len >= 6, 'version output is too short to carry its provenance lines:\n${r.output}'
	head := lines[0]

	// The commit stamp the binary reports on its own `commit` line.
	commit_lines := lines.filter(it.starts_with('  commit '))
	assert commit_lines.len == 1, 'exactly one commit line expected:\n${r.output}'
	commit := commit_lines[0].all_after('  commit ').trim_space()

	// Exactly two shapes are legal, and they are the two the formatter emits —
	// so the binary's headline is checked against the SAME function the
	// state-table test above pins, not against a re-spelled expectation.
	release_head := cli.version_headline(ver, 'release', commit)
	dev_head := cli.version_headline(ver, 'dev', commit)
	assert head in [release_head, dev_head], 'headline is neither ruled shape (want "${release_head}" or "${dev_head}"):\n${r.output}'

	// A dev tree MUST NOT claim the release. The converse is deliberately not
	// asserted: a binary built at a tag and then left behind by a later commit
	// is a stale build, not a false claim, and the release lane rebuilds.
	state := makefile_release_state()
	if state == 'dev' {
		assert head == dev_head, 'this tree is not at the v${ver} tag (or is dirty), so the headline must be the pre-release form "${dev_head}":\n${r.output}'
		assert head.contains('-dev+'), 'a non-release build must carry the -dev+ pre-release marker: ${head}'
	} else if state == '' {
		eprintln('NOTE: `make print-CX_RELEASE` unavailable — headline shape checked, build state not cross-checked')
	}

	// `cx version` and `cx --version` are one surface (pinned above); the
	// headline is therefore the same claim however it is asked for.
	verb := os.execute('${cx_bin()} version')
	assert verb.exit_code == 0
	assert verb.output.split_into_lines()[0] == head, 'the verb and the flag must make the same provenance claim'
}

// ── 8c. #666's CX_DIRTY derivation, directly (#984 rider) ───────────────────
//
// #666 and #667 shipped the -dirty stamp UNTESTED: the CO-4 headline test
// above covers -dirty only where it rides into build metadata, so nothing held
// the derivation itself. It is the load-bearing half of two claims — the
// commit stamp (#666: a stamp naming a commit that does not reproduce the
// artifact is unfalsifiable) and the release state (#979: HEAD at the tag AND
// a clean tree) — and it is one shell substitution that could silently stop
// detecting anything at all.
//
// Two things are pinned. The DERIVATION, against git as the oracle: unlike
// CO-4's release state, whose one implementation the test must not re-spell,
// "is this tree modified" has an authority outside the Makefile, and asking it
// is what gives the pin detection power. And the COMPOSITION: CX_COMMIT ends
// with the marker, and a dirty tree can never be a release. The lane sees both
// states over its life — a dev checkout is dirty, CI is clean.

fn test_makefile_cx_dirty_derivation() {
	dirty := makefile_var('CX_DIRTY') or {
		eprintln('NOTE: `make print-CX_DIRTY` unavailable — CX_DIRTY derivation not checked')
		return
	}
	assert dirty in ['', '-dirty'], 'CX_DIRTY is a stamp suffix, not a flag: got "${dirty}"'

	// The oracle: the same question the Makefile asks git, asked directly.
	// --untracked-files=no is part of the contract — an untracked scratch file
	// is not a modification of the artifact's sources.
	repo := os.dir(@VMODROOT)
	g := os.execute('git -C ${os.quoted_path(repo)} status --porcelain --untracked-files=no 2>/dev/null')
	if g.exit_code != 0 {
		eprintln('NOTE: not a git checkout — CX_DIRTY value not cross-checked')
	} else {
		modified := g.output.trim_space() != ''
		want := if modified { '-dirty' } else { '' }
		assert dirty == want, 'CX_DIRTY must be "${want}" for this tree (git reports ${g.output.split_into_lines().len} modified path(s)), got "${dirty}"'
	}

	// #666's composition: the marker rides on the commit stamp.
	commit := makefile_var('CX_COMMIT') or { return }
	assert commit != '', 'CX_COMMIT is never empty — it falls back to "unknown"'
	if dirty == '-dirty' {
		assert commit.ends_with('-dirty'), 'a dirty tree must mark the commit stamp: got "${commit}"'
		// #979's clean-tree half: no tag can vouch for a modified tree.
		state := makefile_release_state()
		if state != '' {
			assert state == 'dev', 'a dirty tree can never derive the release state: got "${state}"'
		}
	} else {
		assert !commit.ends_with('-dirty'), 'a clean tree must not mark the commit stamp: got "${commit}"'
	}
}

// ── 9. The four flagship tours run their documented --data lines ─────────────

fn test_flagship_tours_documented_run_lines_work() {
	root := os.dir(@VMODROOT)
	tours := ['code-tour', 'cxpath-tour', 'match-multi', 'modify-crud']
	for t in tours {
		tour := os.join_path(root, 'examples', '${t}.cx')
		inp := os.join_path(root, 'examples', '${t}.input.cx')
		if !os.is_file(tour) || !os.is_file(inp) {
			eprintln('SKIP tour ${t}: examples not present at ${tour}')
			continue
		}
		r := os.execute('${cx_bin()} --data=${inp} ${tour}')
		head := if r.output.len > 500 { r.output[..500] } else { r.output }
		assert r.exit_code == 0, 'tour ${t} --data run failed (${r.exit_code}): ${head}'
		assert r.output.trim_space().len > 0, 'tour ${t} produced no output'
	}
}

// ── 8. RULED R5.13 — a top-level `err` RESULT exits 1 ───────────────────────
//
// Normative: cli.md §3.7.1. CX has no `exit` and no `raise` directive, so a
// program declines by RETURNING an err — and returning one used to exit 0,
// making a refusal indistinguishable from success to `make`, to CI, and to a
// supervisor watching a long-running program. The webhook adapter's R5.12
// refusal is the case that forced the ruling.
//
// The discriminator is POSITION, not value (code.md §6.4.1's rule, inherited
// rather than invented): a source-literal `[err …]` as the program's OWN
// top-level form is DATA. Every assertion below pairs the status with the
// OUTPUT, because the rule must move the exit code and nothing else.

fn test_computed_top_level_err_exits_1() {
	f := tmp_file_run('r513_computed', "[?element 'err' [?attr 'code' 'cx-err:CXER9999']]\n")
	defer {
		os.rm(f) or {}
	}
	res := os.execute('${cx_bin()} ${f}')
	assert res.exit_code == 1, 'a computed top-level err must exit 1: rc=${res.exit_code} ${res.output}'
	// the err is still the program's ANSWER and still goes to stdout
	assert res.output.contains('CXER9999'), 'the err must still be rendered: ${res.output}'
}

fn test_literal_top_level_err_is_data_and_exits_0() {
	// the half that keeps err-shaped DOCUMENTS expressible. If this ever goes
	// red, every `[err …]`-shaped data file has become a failing program.
	f := tmp_file_run('r513_literal', "[err code='cx-err:CXER9999' message='data']\n")
	defer {
		os.rm(f) or {}
	}
	res := os.execute('${cx_bin()} ${f}')
	assert res.exit_code == 0, 'a source-literal top-level err is DATA and must exit 0: rc=${res.exit_code} ${res.output}'
	assert res.output.contains('CXER9999'), 'the data document must still render: ${res.output}'
}

fn test_propagated_err_through_a_call_exits_1() {
	// #853: an err in CALL-OPERAND position short-circuits the call, so the
	// result is the err even though the source spelling is a call. Position,
	// not value — the literal carve-out is for the TOP-LEVEL FORM only.
	f := tmp_file_run('r513_propagated', "[?lib 'cx-stdlib/format' :as format]\n[\$format:canonical [err code='c' message='m']]\n")
	defer {
		os.rm(f) or {}
	}
	res := os.execute('${cx_bin()} ${f}')
	assert res.exit_code == 1, 'a propagated err result must exit 1: rc=${res.exit_code} ${res.output}'
}

fn test_err_nested_in_a_surviving_structure_exits_0() {
	// not a top-level result: the wrapper survived, so the program did not fail.
	f := tmp_file_run('r513_nested', "[wrapper [err code='c']]\n")
	defer {
		os.rm(f) or {}
	}
	res := os.execute('${cx_bin()} ${f}')
	assert res.exit_code == 0, 'an err nested in a surviving structure must exit 0: rc=${res.exit_code} ${res.output}'
	assert res.output.contains('[wrapper'), 'the wrapper must survive: ${res.output}'
}

fn test_multi_form_classifies_each_form_against_its_own_spelling() {
	// The multi-form path does NOT index-align results with source items —
	// declaration directives evaluate but contribute no output — so these two
	// pin that the pairing is right rather than off by the number of decls.
	lit := tmp_file_run('r513_multi_lit', "[a 1]\n[err code='c' message='literal']\n")
	comp := tmp_file_run('r513_multi_comp', "[a 1]\n[?element 'err' [?attr 'code' 'c']]\n")
	defer {
		os.rm(lit) or {}
		os.rm(comp) or {}
	}
	r_lit := os.execute('${cx_bin()} ${lit}')
	assert r_lit.exit_code == 0, 'a literal err form in a multi-form document is DATA: rc=${r_lit.exit_code} ${r_lit.output}'
	assert r_lit.output.contains('[a 1]'), 'both forms must render: ${r_lit.output}'

	r_comp := os.execute('${cx_bin()} ${comp}')
	assert r_comp.exit_code == 1, 'ANY failing top-level form fails the program: rc=${r_comp.exit_code} ${r_comp.output}'
	assert r_comp.output.contains('[a 1]'), 'output bytes are unchanged by the status: ${r_comp.output}'

	// and a decl BEFORE the err form must not shift the pairing
	withdecl := tmp_file_run('r513_multi_decl', "[?lib 'cx-stdlib/format' :as format]\n[a 1]\n[err code='c' message='literal']\n")
	defer {
		os.rm(withdecl) or {}
	}
	r_decl := os.execute('${cx_bin()} ${withdecl}')
	assert r_decl.exit_code == 0, 'a [?lib] decl must not shift form pairing: rc=${r_decl.exit_code} ${r_decl.output}'
}

fn test_ordinary_program_still_exits_0() {
	// the control: R5.13 must not make successful programs fail.
	f := tmp_file_run('r513_ok', '[ok [value 1]]\n')
	defer {
		os.rm(f) or {}
	}
	res := os.execute('${cx_bin()} ${f}')
	assert res.exit_code == 0, 'an ordinary program must still exit 0: rc=${res.exit_code} ${res.output}'
}

// ── 10. #926 RULED: PYE-2 + PYE-3 — the program argument vector ─────────────
//
// Normative: cli.md §3.7 (the positional rule) + env.md §3.2/§7. The surface
// is `cx [flags] RESOURCE [args...]`; everything after the resource is the
// program's argv, delivered as [resource, ...args] (sys.argv shape) through
// $env:argv — UNGATED (PYE-3: no --allow-* flag appears in ANY invocation in
// this section). The invariant under test: a program's view of its arguments
// is independent of how it was launched (FILE / shebang / -e / stdin).

const argv_prog = "[?lib 'cx-stdlib/env']\n[$env:argv]\n"

fn test_pye2_file_argv_is_resource_plus_args() {
	prog := tmp_file_run('pye2_file', argv_prog)
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin()} ${prog} alpha beta')
	assert r.exit_code == 0, 'cx FILE args must run (ungranted, PYE-3): ${r.output}'
	assert r.output.contains(prog), 'argv[0] must be the FILE path: ${r.output}'
	assert r.output.contains('alpha') && r.output.contains('beta'), 'program args missing: ${r.output}'
}

fn test_pye2_flag_shaped_tokens_after_file_are_program_args() {
	// The BREAKING half of the cutover: a cx flag written after the resource
	// is a PROGRAM argument — no error, no cx-flag effect.
	prog := tmp_file_run('pye2_flagargs', argv_prog)
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin()} ${prog} --verbose in.txt --json 2>&1')
	assert r.exit_code == 0, 'flag-shaped program args must not error: ${r.output}'
	assert r.output.contains('--verbose') && r.output.contains('in.txt'), 'flag-shaped args must reach argv verbatim: ${r.output}'
	// --json bound to the PROGRAM, not to cx: output stays canonical CX
	// (a JSON rendering of the sequence would open with '[').
	assert r.output.trim_space().starts_with('('), '--json after FILE must NOT select JSON rendering: ${r.output}'
}

fn test_pye2_shebang_matches_cx_file_invocation() {
	// Shebang and `cx FILE` must be IDENTICAL (the PYE-2 invariant). The
	// script is executed directly; the kernel hands cx `script args...`.
	dir := os.join_path(os.temp_dir(), 'cx_pye2_shebang_${os.getpid()}')
	os.mkdir_all(dir) or { panic(err) }
	defer { os.rmdir_all(dir) or {} }
	script := os.join_path(dir, 'tool.cx')
	os.write_file(script, '#!${cx_bin()}\n${argv_prog}') or { panic(err) }
	os.chmod(script, 0o755) or { panic(err) }
	direct := os.execute('${script} alpha --flag')
	via_cx := os.execute('${cx_bin()} ${script} alpha --flag')
	assert direct.exit_code == 0, 'shebang run must succeed: ${direct.output}'
	assert direct.output == via_cx.output, 'shebang and cx FILE must see IDENTICAL argv:\n${direct.output}\nvs\n${via_cx.output}'
	assert direct.output.contains('alpha') && direct.output.contains('--flag'), 'shebang args missing: ${direct.output}'
}

fn test_pye2_inline_e_argv0_is_dash_e() {
	// argv[0] placeholder for the inline launch mode: '-e' (pinned).
	r := os.execute("${cx_bin()} -e '[?lib \"cx-stdlib/env\"] [\$env:argv]' alpha")
	assert r.exit_code == 0, '-e with program args must run: ${r.output}'
	assert r.output.contains('-e') && r.output.contains('alpha'), "argv must be ('-e', alpha): ${r.output}"
}

fn test_pye2_stdin_argv0_is_stdin_placeholder() {
	// argv[0] placeholder for stdin programs: 'stdin' (pinned) — both the
	// explicit `-` and the pipe fall-through.
	prog := tmp_file_run('pye2_stdin_src', argv_prog)
	defer { os.rm(prog) or {} }
	r := os.execute('cat ${prog} | ${cx_bin()} - alpha beta')
	assert r.exit_code == 0, 'cx - args must run: ${r.output}'
	assert r.output.contains('stdin') && r.output.contains('alpha'), "argv must be (stdin, alpha, beta): ${r.output}"
	r2 := os.execute('cat ${prog} | ${cx_bin()}')
	assert r2.exit_code == 0, 'pipe fall-through must run: ${r2.output}'
	assert r2.output.contains('stdin'), "pipe fall-through argv must be (stdin): ${r2.output}"
}

fn test_pye3_parse_args_reachable_and_ungated() {
	// The #926 headline: env:parse-args over REAL program args, with ZERO
	// capability grants on the invocation.
	prog := tmp_file_run('pye3_parse', "[?lib 'cx-stdlib/env']\n[?let [= \$spec [argspec [flag name=verbose short=v type=\"bool\"] [flag name=limit short=n type=\"int\" default=100]]]\n  [= \$parsed [\$env:parse-args \$spec]]\n  ([\$env:flag \$parsed \"verbose\"], [\$env:flag \$parsed \"limit\"])]\n")
	defer { os.rm(prog) or {} }
	r := os.execute('${cx_bin()} ${prog} --verbose --limit 10')
	assert r.exit_code == 0, 'parse-args over program args must run ungranted: ${r.output}'
	assert r.output.contains('true') && r.output.contains('10'), 'parsed flags wrong: ${r.output}'
	// Control: $env:var STAYS gated (deny-by-default) — argv ungated is not
	// a widening of the env grant.
	prog2 := tmp_file_run('pye3_var', "[?lib 'cx-stdlib/env']\n[\$env:var \"HOME\"]\n")
	defer { os.rm(prog2) or {} }
	r2 := os.execute('${cx_bin()} ${prog2} 2>&1')
	assert r2.exit_code != 0, 'env var read must stay denied without --allow-env: ${r2.output}'
	assert r2.output.contains('CXER0271'), 'denial must name the cap error: ${r2.output}'
}

fn test_pye2_convert_surface_refuses_trailing_args() {
	// The convert surface has no program to receive trailing args — they
	// are refused loudly (the #415 no-silent-swallow rule): `cx data.json
	// --to=xml` used to convert; silently ignoring the now-trailing flag
	// would emit the default format as if it were the asked-for one.
	doc := tmp_file_run('pye2_conv', '[a 1]\n')
	defer { os.rm(doc) or {} }
	r := os.execute('${cx_bin()} --from=cx ${doc} --to=xml 2>&1')
	assert r.exit_code == 2, 'trailing args on the convert surface must exit 2: ${r.output}'
	assert r.output.contains('--to=xml'), 'diagnostic must name the trailing tokens: ${r.output}'
	// flag-first spelling still converts
	r2 := os.execute('${cx_bin()} --from=cx --to=xml ${doc}')
	assert r2.exit_code == 0 && r2.output.contains('<a>'), 'flag-first convert broken: ${r2.output}'
}

fn test_pye2_eval_alias_matches_run_surface_argv() {
	// `cx eval` is the documented alias: same positional rule, same argv.
	prog := tmp_file_run('pye2_eval', argv_prog)
	defer { os.rm(prog) or {} }
	run := os.execute('${cx_bin()} ${prog} alpha')
	alias := os.execute('${cx_bin()} eval ${prog} alpha')
	assert alias.exit_code == 0, 'cx eval FILE args must run: ${alias.output}'
	assert run.output == alias.output, 'run surface and eval alias must see identical argv:\n${run.output}\nvs\n${alias.output}'
}

// ── A mistyped VERB is named as one, never as a missing file (#970, CO-6) ────
//
// `cx store-token` fell through the subcommand table to the run surface and
// reported `error reading file store-token: failed to open file
// "store-token"` — which reads as a broken install rather than as "there is
// no such subcommand". The verb reading applies to argv[0] only, and the
// discriminator is FILE EXISTENCE, never name shape: the run surface is
// `cx RESOURCE` and a resource needs no extension, so an extensionless file
// that EXISTS still runs (that non-regression is pinned below).

// A scratch directory with no file that could shadow the tokens under test.
fn clean_dir(label string) string {
	dir := os.join_path(os.temp_dir(), 'cx_970_${label}_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic(err) }
	return dir
}

fn test_unknown_verb_is_named_not_reported_as_a_missing_file() {
	dir := clean_dir('unknown')
	defer { os.rmdir_all(dir) or {} }
	r := os.execute('cd ${dir} && ${cx_bin()} frobnicate-store 2>&1')
	assert r.exit_code == 2, 'unknown subcommand must exit 2, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('unknown subcommand'), 'diagnostic must say unknown subcommand: ${r.output}'
	assert r.output.contains('frobnicate-store'), 'diagnostic must name the verb: ${r.output}'
	assert r.output.contains('--help'), 'diagnostic must point at the catalog: ${r.output}'
	// The #970 repro shape is GONE: no missing-file wording for a verb word.
	assert !r.output.contains('failed to open file'), 'the #970 missing-file wording must be gone: ${r.output}'
	assert !r.output.contains('error reading file'), 'the #970 missing-file wording must be gone: ${r.output}'
}

fn test_retired_verb_names_its_own_retirement() {
	// RULED: CO-6 — a RETIRED verb word (store-token) answers with its
	// retirement and its replacement, never 'unknown subcommand' and never
	// the missing-file fall-through. The #426 lesson applied to retirement.
	dir := clean_dir('retired')
	defer { os.rmdir_all(dir) or {} }
	r := os.execute('cd ${dir} && ${cx_bin()} store-token 2>&1')
	assert r.exit_code == 2, 'a retired verb must exit 2, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('retired'), 'diagnostic must say retired: ${r.output}'
	assert r.output.contains('store-token'), 'diagnostic must name the verb: ${r.output}'
	assert r.output.contains('XSP-AUTH'), 'diagnostic must name the replacement: ${r.output}'
	assert !r.output.contains('unknown subcommand'), 'a retired verb is not unknown: ${r.output}'
	assert !r.output.contains('failed to open file'), 'no missing-file wording for a retired verb: ${r.output}'
}

fn test_unknown_verb_does_not_shadow_an_existing_extensionless_file() {
	// The CRITICAL non-regression: file existence decides, not name shape.
	// A verb-shaped, extension-free, EXISTING file still runs as a program.
	dir := clean_dir('extless')
	defer { os.rmdir_all(dir) or {} }
	os.write_file(os.join_path(dir, 'store-token'), '[+ 20 3]\n') or { panic(err) }
	r := os.execute('cd ${dir} && ${cx_bin()} store-token 2>&1')
	assert r.exit_code == 0, 'an existing extensionless file must still run, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('23'), 'the extensionless program did not evaluate: ${r.output}'
	assert !r.output.contains('unknown subcommand'), 'an EXISTING file must never read as a verb: ${r.output}'
	assert !r.output.contains('retired'), 'file existence beats even the RETIRED reading (CO-6): ${r.output}'
}

fn test_missing_cx_file_stays_a_missing_file_error() {
	// A dotted token was unambiguously meant as a RESOURCE — it could never
	// have been a subcommand word, so the missing-file diagnostic stands.
	dir := clean_dir('dotted')
	defer { os.rmdir_all(dir) or {} }
	r := os.execute('cd ${dir} && ${cx_bin()} definitely_absent.cx 2>&1')
	assert r.exit_code == 1, 'a missing .cx resource must exit 1, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('definitely_absent.cx'), 'diagnostic must name the file: ${r.output}'
	assert !r.output.contains('unknown subcommand'), 'a dotted token must not read as a verb: ${r.output}'
}

fn test_missing_path_token_stays_a_missing_file_error() {
	// Likewise for a token carrying a path separator.
	dir := clean_dir('path')
	defer { os.rmdir_all(dir) or {} }
	r := os.execute('cd ${dir} && ${cx_bin()} sub/store-token 2>&1')
