fn test_verb_reading_applies_to_argv0_only() {
	// After a cx flag the token is positionally a RESOURCE, not a verb word —
	// the subcommand table is never consulted there, so a missing one keeps
	// the missing-file diagnostic.
	dir := clean_dir('flagged')
	defer { os.rmdir_all(dir) or {} }
	r := os.execute('cd ${dir} && ${cx_bin()} --json store-token 2>&1')
	assert r.exit_code == 1, 'a resource after a flag must exit 1, got ${r.exit_code}: ${r.output}'
	assert !r.output.contains('unknown subcommand'), 'only argv[0] gets the verb reading: ${r.output}'
}

// ── #969 / RULED: CO-5 — the offline XSP-AUTH principal mint ────────────────
//
// `cx store-mint-principal` is the clean-state bootstrap a deny-by-default
// daemon needs: it MINTS AN IDENTITY (never a bearer), entirely offline. The
// lanes below drive the built binary and pin the contract the docs and the
// spec's §3.9 quote: the seed lands 0600 and is never printed, the DID is
// derived from THAT seed, and stdout is one parseable CX element whose
// [config-stanza] is the verbatim daemon-config shape.

fn smp_dir(label string) string {
	dir := os.join_path(os.temp_dir(), 'cx_969_${label}_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic(err) }
	return dir
}

fn test_mint_principal_writes_a_0600_seed_and_prints_a_parseable_stanza() {
	dir := smp_dir('mint')
	defer { os.rmdir_all(dir) or {} }
	seed := os.join_path(dir, 'ops.seed')
	// os.execute MERGES stderr into .output, and this verb deliberately splits
	// the machine-readable report (stdout) from the operator prose (stderr) —
	// so the stdout-shape lanes drop stderr to read the contract they pin.
	r := os.execute('${cx_bin()} store-mint-principal --id ops --seed-file ${seed} --caps "read write" 2>/dev/null')
	assert r.exit_code == 0, 'mint must exit 0, got ${r.exit_code}: ${r.output}'

	// (a) the seed file exists, is 0600, and holds a 32-byte hex seed.
	assert os.exists(seed), 'the seed file was not created: ${r.output}'
	st := os.stat(seed) or {
		assert false, 'cannot stat the seed file: ${err}'
		return
	}
	mode := st.mode & 0o777
	assert mode == 0o600, 'the seed file must be 0600, got ${mode:o}'
	seed_hex := os.read_file(seed) or {
		assert false, 'cannot read the seed file: ${err}'
		return
	}
	assert seed_hex.trim_space().len == 64, 'the seed must be 32 bytes of hex, got "${seed_hex.trim_space()}"'
	for c in seed_hex.trim_space() {
		ok := (c >= `0` && c <= `9`) || (c >= `a` && c <= `f`)
		assert ok, 'the seed file must hold lowercase hex, got "${seed_hex.trim_space()}"'
	}

	// (b) the SECRET never reaches stdout — the whole point of --seed-file.
	assert !r.output.contains(seed_hex.trim_space()), 'the seed must NEVER be printed: ${r.output}'

	// (c) stdout is ONE parseable CX document (the deterministic layout the
	// spec's §3.9 and the store-service walkthrough both quote).
	doc := cx.parse(r.output) or {
		assert false, 'stdout must parse as CX, got: ${r.output}\n${err}'
		return
	}
	assert doc.elements.len == 1, 'stdout must be exactly one element: ${r.output}'
	root := doc.elements[0] as cx.Element
	assert root.name == 'xsp-principal', 'the report root must be [xsp-principal …], got [${root.name}]'
	assert root.attr('id') == 'ops', 'the report must carry the id: ${r.output}'
	// #985 (ii): the report names WHICH daemon row it carries, so a machine
	// consumer never sniffs the children to find out.
	assert root.attr('for') == 'grant', 'the default row is a grant row: ${r.output}'
	assert root.attr('seed-file') == seed, 'the report must name the seed file: ${r.output}'
	assert root.attr('seed-env') == 'CX_XSP_SEED_OPS', 'seed-env is DERIVED from --id: got "${root.attr('seed-env')}"'
	did := root.attr('did')
	assert did.starts_with('did:key:z'), 'the minted DID must be a did:key, got "${did}"'

	// (d) the grant stanza is the shape store_service.v's svc_parse_xsp reads:
	// [xsp [grants [grant did=… caps=…]]] with caps from the v1 grammar.
	mut grant := cx.Element{}
	mut opts := cx.Element{}
	for ch in root.items {
		if ch is cx.Element {
			if ch.name == 'config-stanza' {
				xsp := ch.items[0] as cx.Element
				assert xsp.name == 'xsp', 'the stanza must be rooted at [xsp …], got [${xsp.name}]'
				grants := xsp.items[0] as cx.Element
				assert grants.name == 'grants', 'the stanza must hold [grants …], got [${grants.name}]'
				grant = grants.items[0] as cx.Element
			}
			if ch.name == 'client-opts' {
				opts = ch.items[0] as cx.Element
			}
		}
	}
	assert grant.name == 'grant', 'the stanza must hold a [grant …] row: ${r.output}'
	assert grant.attr('did') == did, 'the grant must name the minted DID: ${r.output}'
	assert grant.attr('caps') == 'read write', 'the STATED caps ride into the grant row verbatim (there is no default since #985): ${r.output}'

	// (e) the client half is the open-opts map the store client reads.
	assert opts.name == 'map', 'client-opts must hold a [map …]: ${r.output}'
	assert opts.attr('xsp-did') == did, 'client-opts must carry xsp-did: ${r.output}'
	assert opts.attr('xsp-seed-env') == 'CX_XSP_SEED_OPS', 'client-opts must carry xsp-seed-env: ${r.output}'

	// (f) the guidance rides stderr (store-rotate-kek's split), naming both
	// halves — stdout stays machine-readable.
	e := os.execute('${cx_bin()} store-mint-principal --id ops2 --seed-file ${dir}/ops2.seed --caps "read" 2>&1 >/dev/null')
	assert e.output.contains('CX_XSP_SEED_OPS2'), 'stderr must show the export line: ${e.output}'
	assert e.output.contains('xsp-seed-env'), 'stderr must show the client usage: ${e.output}'
}

fn test_mint_principal_seed_proves_control_of_the_printed_did() {
	// A mint that printed a DID its own seed could not prove would hand the
	// operator a credential the daemon refuses. This drives the SHIPPED
	// stdlib surface — sign a challenge with the written seed, then check
	// proof-of-control against the printed DID — which is the same equality
	// [xsp [identity]] asserts at startup and the client asserts at attach.
	// Both calls are pure, so no capability flags are needed.
	dir := smp_dir('control')
	defer { os.rmdir_all(dir) or {} }
	seed := os.join_path(dir, 'p.seed')
	r := os.execute('${cx_bin()} store-mint-principal --id p --seed-file ${seed} --caps "read" 2>/dev/null')
	assert r.exit_code == 0, 'mint exited ${r.exit_code}: ${r.output}'
	doc := cx.parse(r.output) or {
		assert false, 'stdout must parse: ${err}'
		return
	}
	did := (doc.elements[0] as cx.Element).attr('did')
	seed_hex := (os.read_file(seed) or { '' }).trim_space()

	prog := os.join_path(dir, 'control.cx')
	os.write_file(prog, "[?lib 'cx-stdlib/did' :as did]\n" +
		"[?lib 'cx-stdlib/crypto' :as crypto]\n" + "[?lib 'cx-stdlib/bytes' :as bytes]\n" +
		'[?let [= \$seed [\$bytes:from-hex "${seed_hex}"]]\n' +
		' [= \$chal [\$bytes:from-string-utf8 "cx-969-mint-control"]]\n' +
		' [= \$sig [\$crypto:ed25519-sign \$seed \$chal]]\n' +
		' [result [ok [\$did:verify-control "${did}" \$chal \$sig]]]]\n') or { panic(err) }
	d := os.execute('${cx_bin()} ${prog}')
	assert d.exit_code == 0, 'proof-of-control program exited ${d.exit_code}: ${d.output}'
	assert d.output.contains('[ok true]'), 'the written seed must prove control of the printed DID: ${d.output}'
}

fn test_mint_principal_refuses_to_overwrite_and_force_replaces() {
	dir := smp_dir('force')
	defer { os.rmdir_all(dir) or {} }
	seed := os.join_path(dir, 'a.seed')
	first := os.execute('${cx_bin()} store-mint-principal --id a --seed-file ${seed} --caps "read write" 2>/dev/null')
	assert first.exit_code == 0, 'first mint exited ${first.exit_code}: ${first.output}'
	before := (os.read_file(seed) or { '' }).trim_space()

	// Refuse: an existing seed file is a LIVE principal whose grant may
	// already sit in a daemon config — silently replacing it would lock that
	// principal out with no diagnostic.
	again := os.execute('${cx_bin()} store-mint-principal --id a --seed-file ${seed} --caps "read write" 2>&1')
	assert again.exit_code == 1, 'overwriting must exit 1, got ${again.exit_code}: ${again.output}'
	assert again.output.contains('already exists'), 'the refusal must name the cause: ${again.output}'
	assert again.output.contains('--force'), 'the refusal must name the override: ${again.output}'
	unchanged := (os.read_file(seed) or { '' }).trim_space()
	assert unchanged == before, 'a refused mint must NOT touch the existing seed'

	// --force replaces it, and the new principal is a DIFFERENT identity.
	forced := os.execute('${cx_bin()} store-mint-principal --id a --seed-file ${seed} --caps "read write" --force 2>/dev/null')
	assert forced.exit_code == 0, '--force must exit 0, got ${forced.exit_code}: ${forced.output}'
	after := (os.read_file(seed) or { '' }).trim_space()
	assert after != before, '--force must write a NEW seed'
	fst := os.stat(seed) or {
		assert false, 'cannot stat the replaced seed: ${err}'
		return
	}
	assert fst.mode & 0o777 == 0o600, 'the replaced seed must still be 0600'
	d1 := (cx.parse(first.output) or { panic(err) }).elements[0] as cx.Element
	d2 := (cx.parse(forced.output) or { panic(err) }).elements[0] as cx.Element
	assert d1.attr('did') != d2.attr('did'), '--force must mint a distinct DID'
}

fn test_mint_principal_usage_errors_are_exit_2() {
	dir := smp_dir('usage')
	defer { os.rmdir_all(dir) or {} }
	// Missing required flags.
	a := os.execute('${cx_bin()} store-mint-principal --id only 2>&1')
	assert a.exit_code == 2, 'a missing --seed-file must exit 2, got ${a.exit_code}: ${a.output}'
	// An id that could not derive a legal env var name.
	b := os.execute('${cx_bin()} store-mint-principal --id "bad id" --seed-file ${dir}/b.seed --caps "read" 2>&1')
	assert b.exit_code == 2, 'a malformed --id must exit 2, got ${b.exit_code}: ${b.output}'
	assert !os.exists('${dir}/b.seed'), 'a usage error must not leave a seed file behind'
	// A capability outside the v1 grammar the daemon config enforces — the
	// mint refuses rather than printing a stanza store-serve would reject.
	c := os.execute('${cx_bin()} store-mint-principal --id c --seed-file ${dir}/c.seed --caps "read frobnicate" 2>&1')
	assert c.exit_code == 2, 'an unknown capability must exit 2, got ${c.exit_code}: ${c.output}'
	assert c.output.contains('frobnicate'), 'the refusal must name the offending capability: ${c.output}'
	assert !os.exists('${dir}/c.seed'), 'a refused caps list must not leave a seed file behind'
	// And a caps list the grammar DOES accept passes through verbatim.
	d := os.execute('${cx_bin()} store-mint-principal --id d --seed-file ${dir}/d.seed --caps "read write delete admin peer" 2>/dev/null')
	assert d.exit_code == 0, 'the full v1 grammar must be accepted, got ${d.exit_code}: ${d.output}'
	assert d.output.contains("caps='read write delete admin peer'"), 'caps must ride through verbatim: ${d.output}'
}

// ── #985 / RULED: CO-10 — the three mint hardenings ─────────────────────────

fn test_mint_principal_requires_caps_with_no_default() {
	// (iii) CUTOVER, no dual-accept: the authority a grant carries is an
	// EXPLICIT choice at mint time. The retired `read write` default meant a
	// hurried bootstrap silently granted write access it never stated; a
	// missing --caps is now a usage error naming the grammar.
	dir := smp_dir('caps_required')
	defer { os.rmdir_all(dir) or {} }
	bare := os.execute('${cx_bin()} store-mint-principal --id nc --seed-file ${dir}/nc.seed 2>&1')
	assert bare.exit_code == 2, 'a missing --caps must exit 2, got ${bare.exit_code}: ${bare.output}'
	assert bare.output.contains('--caps is required'), 'the refusal must name the missing flag: ${bare.output}'
	assert bare.output.contains('read write delete admin peer'), 'the refusal must name the caps grammar: ${bare.output}'
	assert !os.exists('${dir}/nc.seed'), 'a refused mint must not leave a seed file behind'

	// An EMPTY --caps is a stated-but-invalid list, not an omission — it
	// reaches the grammar check, which names the same v1 list.
	empty := os.execute('${cx_bin()} store-mint-principal --id ec --seed-file ${dir}/ec.seed --caps "" 2>&1')
	assert empty.exit_code == 2, 'an empty --caps must exit 2, got ${empty.exit_code}: ${empty.output}'
	assert empty.output.contains('at least one capability'), 'an empty list must be refused as an empty list: ${empty.output}'
	assert !os.exists('${dir}/ec.seed'), 'a refused caps list must not leave a seed file behind'
}

fn test_mint_principal_refuses_a_noncanonical_id_that_aliases_another() {
	// (i) CX_XSP_SEED_<NAME> upper-cases the id and folds `-` to `_`, so the
	// derivation is many-to-one: several spellings land on ONE env var, and
	// two principals minted under two of them would silently share one seed
	// variable (only the last exported works, and the other principal
	// presents a seed that does not derive its DID).
	//
	// The verb holds NO state — there is no registry of past mints to
	// consult — so it refuses non-canonical spellings instead, which makes
	// the derivation injective over the ids it accepts. That is the stronger
	// guarantee: it holds across hosts and across time, not merely within
	// one recorded file.
	dir := smp_dir('canon')
	defer { os.rmdir_all(dir) or {} }

	// The canonical spelling mints, and its env var is the one at issue.
	ok := os.execute('${cx_bin()} store-mint-principal --id fleet-ops --seed-file ${dir}/ok.seed --caps "read" 2>/dev/null')
	assert ok.exit_code == 0, 'the canonical id must mint, got ${ok.exit_code}: ${ok.output}'
	assert ok.output.contains('CX_XSP_SEED_FLEET_OPS'), 'the canonical id derives the env var under test: ${ok.output}'

	// Every aliasing spelling is refused, and the refusal names BOTH ids and
	// the variable they would have shared — the operator's real question is
	// "what should I have typed", and this failure is otherwise invisible.
	for alias in ['fleet_ops', 'Fleet-Ops', 'FLEET_OPS', 'FLEET-OPS'] {
		r := os.execute('${cx_bin()} store-mint-principal --id ${alias} --seed-file ${dir}/${alias}.seed --caps "read" 2>&1')
		assert r.exit_code == 2, 'the aliasing id "${alias}" must exit 2, got ${r.exit_code}: ${r.output}'
		assert r.output.contains('"${alias}"'), 'the refusal must name the id as typed: ${r.output}'
		assert r.output.contains('"fleet-ops"'), 'the refusal must name the canonical id it collides with: ${r.output}'
		assert r.output.contains('CX_XSP_SEED_FLEET_OPS'), 'the refusal must name the shared env var: ${r.output}'
		assert !os.exists('${dir}/${alias}.seed'), 'a refused mint must not leave a seed file behind'
	}

	// Digits and interior hyphens stay legal — only the ALIASING characters
	// (uppercase, `_`) are refused, so the accepted alphabet is still a
	// useful operator vocabulary.
	fine := os.execute('${cx_bin()} store-mint-principal --id ops-2 --seed-file ${dir}/ops2.seed --caps "read" 2>/dev/null')
	assert fine.exit_code == 0, 'a lowercase hyphenated id must mint, got ${fine.exit_code}: ${fine.output}'
	assert fine.output.contains('CX_XSP_SEED_OPS_2'), 'the derivation still folds `-` to `_`: ${fine.output}'
}

fn test_mint_principal_for_identity_emits_the_daemon_identity_row() {
	// (ii) `--for identity` prints the daemon's OWN responder row so the
	// walkthrough's daemon step is copy-paste rather than prose. The row is
	// built from platform.xsp_identity_attrs — the very list svc_parse_xsp
	// validates it against — so the attribute set below is the parser's, not
	// a second spelling of it.
	dir := smp_dir('identity')
	defer { os.rmdir_all(dir) or {} }
	seed := os.join_path(dir, 'host.seed')
	r := os.execute('${cx_bin()} store-mint-principal --id host --seed-file ${seed} --for identity 2>/dev/null')
	assert r.exit_code == 0, '--for identity must exit 0, got ${r.exit_code}: ${r.output}'
	doc := cx.parse(r.output) or {
		assert false, 'stdout must parse as CX, got: ${r.output}\n${err}'
		return
	}
	root := doc.elements[0] as cx.Element
	assert root.attr('for') == 'identity', 'the report must name the row it carries: ${r.output}'
	did := root.attr('did')

	mut ident := cx.Element{}
	for ch in root.items {
		if ch is cx.Element {
			if ch.name == 'config-stanza' {
				xsp := ch.items[0] as cx.Element
				assert xsp.name == 'xsp', 'the stanza must be rooted at [xsp …], got [${xsp.name}]'
				ident = xsp.items[0] as cx.Element
			}
		}
	}
	// The daemon row REPLACES the grant row — an identity mint that also
	// printed a grant would invite an operator to grant the daemon to itself.
	assert ident.name == 'identity', 'the stanza must hold the [identity …] row, got [${ident.name}]: ${r.output}'
	assert ident.attrs.len == 2, 'the identity row carries exactly did= and seed-env=: ${r.output}'
	assert ident.attrs[0].name == 'did', 'attribute 0 is did= (svc_parse_xsp\'s xsp_identity_attrs order): ${r.output}'
	assert ident.attrs[1].name == 'seed-env', 'attribute 1 is seed-env=: ${r.output}'
	assert ident.attr('did') == did, 'the identity row must carry the minted DID: ${r.output}'
	assert ident.attr('seed-env') == 'CX_XSP_SEED_HOST', 'seed-env is DERIVED from --id: ${r.output}'
	assert !r.output.contains('grants'), 'an identity mint prints no grant row: ${r.output}'
	// The seed discipline does not relax for the daemon's own identity.
	st := os.stat(seed) or {
		assert false, 'cannot stat the seed file: ${err}'
		return
	}
	assert st.mode & 0o777 == 0o600, 'the daemon seed must be 0600 too'

	// The guidance follows the row: export BEFORE store-serve, because the
	// daemon resolves seed-env while parsing its config.
	g := os.execute('${cx_bin()} store-mint-principal --id host2 --seed-file ${dir}/host2.seed --for identity 2>&1 >/dev/null')
	assert g.output.contains('[identity'), 'stderr must point at the identity row: ${g.output}'
	assert g.output.contains('CX_XSP_SEED_HOST2'), 'stderr must show the export line: ${g.output}'

	// --caps has no home in an identity row, so stating one is a usage error
	// rather than a silently dropped authority choice.
	c := os.execute('${cx_bin()} store-mint-principal --id host3 --seed-file ${dir}/host3.seed --for identity --caps "read write" 2>&1')
	assert c.exit_code == 2, '--caps with --for identity must exit 2, got ${c.exit_code}: ${c.output}'
	assert c.output.contains('--caps does not apply'), 'the refusal must name the flag: ${c.output}'
	assert !os.exists('${dir}/host3.seed'), 'a refused mint must not leave a seed file behind'

	// An unknown row is a usage error naming both rows it can print.
	u := os.execute('${cx_bin()} store-mint-principal --id host4 --seed-file ${dir}/host4.seed --for bearer --caps "read" 2>&1')
	assert u.exit_code == 2, 'an unknown --for must exit 2, got ${u.exit_code}: ${u.output}'
	assert u.output.contains('grant') && u.output.contains('identity'), 'the refusal must name both rows: ${u.output}'
	assert !os.exists('${dir}/host4.seed'), 'a refused mint must not leave a seed file behind'
}

fn test_registered_verbs_still_dispatch_under_the_unknown_verb_guard() {
	// Control: the guard sits AFTER the registry loop, so a registered
	// verb-shaped name still dispatches even though no such file exists.
	// (cli_umbrella_test.v pins the FULL roster answering -h/--help; this is
	// the same invariant read from the guard's side.)
	dir := clean_dir('control')
	defer { os.rmdir_all(dir) or {} }
	r := os.execute('cd ${dir} && ${cx_bin()} version 2>&1')
	assert r.exit_code == 0, 'cx version must still dispatch, got ${r.exit_code}: ${r.output}'
	assert r.output.starts_with('cx v'), 'cx version must not hit the guard: ${r.output}'
	// And the uniform per-verb help still wins over the guard.
	h := os.execute('cd ${dir} && ${cx_bin()} lint --help 2>&1')
	assert h.exit_code == 0, 'cx lint --help must exit 0, got ${h.exit_code}: ${h.output}'
	assert !h.output.contains('unknown subcommand'), 'registered verb help must not hit the guard: ${h.output}'
}

// ── #1019: the CONVERT surface names its own lane on an E211 refusal ─────────
//
// The issue reported a three-way split — `cx --ast` refuses (E211) what the
// evaluator runs, and the walker images a third answer. The disposition
// (ledger/rulings_2026_08_25_0170_closeout.md, "#1019 disposition") is WORKS
// AS SPECIFIED: code.md §6.4.1 states the scalar constraint AT EVAL, lexicon
// §10 D2 refuses the bracket opener AT PARSE, and DATA ⊆ PROGRAM (code.md
// §1.3) makes program-accepts / data-rejects the CONTRACTED direction. What
// was missing was ORIENTATION, so `--ast` now appends ONE line naming the
// lane — and ONLY when the refused source is actually program-shaped.
//
// These pins are the red-proof for that line in both directions: remove the
// eprintln and (a) goes red; remove the `source_carries_program_directive`
// guard and (b)/(c)/(d) go red on a line that should not be there.

fn tmp_file_convert(label string, content string) string {
	path := os.join_path(os.temp_dir(), 'cx_cli_conv_${label}_${os.getpid()}.cx')
	os.write_file(path, content) or { panic(err) }
	return path
}

const convert_e211_note = 'this resource is program-shaped; --ast is the DATA projection (cli.md §2.2)'

// (a) program-shaped source: the refusal stands AND is oriented.
fn test_ast_e211_on_program_shaped_source_names_the_lane() {
	f := tmp_file_convert('prog', '[?def f (\$a) \$a]\n[m x=[\$f 1]]\n')
	defer {
		os.rm(f) or {}
	}
	r := os.execute('${cx_bin()} --ast --compact ${f} 2>&1')
	assert r.exit_code == 1, 'the E211 verdict must be unchanged, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('cx-err:E211'), 'the refusal itself must still be E211: ${r.output}'
	assert r.output.contains(convert_e211_note), 'a program-shaped source must be oriented: ${r.output}'
	// ONE line, not a paragraph — the diagnostic is an orientation, not an essay.
	assert r.output.split_into_lines().filter(it.contains('DATA projection')).len == 1, 'the note must appear exactly once: ${r.output}'
}

// (b) pure DATA source, same E211: no note. A document with no directive in it
// is not program-shaped, and telling its author about the program reading
// would be noise pointing at a lane they never asked for.
fn test_ast_e211_on_pure_data_source_stays_bare() {
	f := tmp_file_convert('data', '[m x=[q]]\n')
	defer {
		os.rm(f) or {}
	}
	r := os.execute('${cx_bin()} --ast --compact ${f} 2>&1')
	assert r.exit_code == 1, 'the E211 verdict must be unchanged, got ${r.exit_code}: ${r.output}'
	assert r.output.contains('cx-err:E211'), 'the refusal itself must still be E211: ${r.output}'
	assert !r.output.contains(convert_e211_note), 'a pure-data source must NOT be oriented: ${r.output}'
}

// (c)/(d) a directive NAMED in a string or a comment is prose, not shape. The
// predicate is string- and comment-aware for the same reason the tree-walking
// `data_reading_has_program_directive` is: documentation ABOUT `[?let]` is not
// a program.
fn test_ast_e211_directive_in_prose_is_not_program_shape() {
	q := tmp_file_convert('quoted', "[doc 'a [?let] mention in prose']\n[m x=[y]]\n")
	defer {
		os.rm(q) or {}
	}
	rq := os.execute('${cx_bin()} --ast --compact ${q} 2>&1')
	assert rq.output.contains('cx-err:E211'), 'the quoted case must still refuse: ${rq.output}'
	assert !rq.output.contains(convert_e211_note), 'a directive inside a string is prose: ${rq.output}'

	c := tmp_file_convert('commented', '# a [?let] in a comment\n[m x=[y]]\n')
	defer {
		os.rm(c) or {}
	}
	rc := os.execute('${cx_bin()} --ast --compact ${c} 2>&1')
	assert rc.output.contains('cx-err:E211'), 'the commented case must still refuse: ${rc.output}'
	assert !rc.output.contains(convert_e211_note), 'a directive inside a comment is prose: ${rc.output}'
}

// (e) the note is scoped to E211. Any other parse refusal on the same lane
// gets no orientation — the line explains a DATA/PROGRAM disagreement, and an
// unterminated element is not one.
fn test_ast_non_e211_refusal_is_not_oriented() {
	f := tmp_file_convert('unterm', '[?def f (\$a) \$a]\n[m x=1\n')
	defer {
		os.rm(f) or {}
	}
	r := os.execute('${cx_bin()} --ast --compact ${f} 2>&1')
	assert r.exit_code == 1, 'an unterminated element must still refuse, got ${r.exit_code}: ${r.output}'
	assert !r.output.contains('cx-err:E211'), 'this case must not be an E211: ${r.output}'
	assert !r.output.contains(convert_e211_note), 'only the E211 refusal is oriented: ${r.output}'
}

// (f) the ACCEPT path is byte-untouched — a resource the data reading admits
// converts exactly as before, note or no note.
fn test_ast_accept_path_unchanged() {
	f := tmp_file_convert('ok', '[?cx version=1]\n[m x=1]\n')
	defer {
		os.rm(f) or {}
	}
	r := os.execute('${cx_bin()} --ast --compact ${f}')
	assert r.exit_code == 0, 'a legal data document must still convert: ${r.output}'
	assert !r.output.contains(convert_e211_note), 'an accepted document is never oriented: ${r.output}'
}

// (g) the predicate itself, read directly — the truth table the CLI pins
// indirectly. `source_carries_program_directive` is the LEXICAL twin of
// `code.data_reading_has_program_directive`: it exists because the tree that
// one walks is exactly what an E211 prevented from being built.
fn test_source_carries_program_directive_truth_table() {
	// Positive: a registered directive at top level, and one nested inside an
	// element body.
	assert cx.source_carries_program_directive('[?let [= \$x 1] \$x]'.bytes())
	assert cx.source_carries_program_directive('[doc [?for \$i (1, 2) \$i]]'.bytes())
	// Negative: no directive at all.
	assert !cx.source_carries_program_directive('[m x=1]'.bytes())
	// Negative: `[?cx …]` is a CONFIG directive and a foreign PI is neither —
	// the same two exclusions the tree-walking predicate makes.
	assert !cx.source_carries_program_directive('[?cx version=1]\n[m]'.bytes())
	assert !cx.source_carries_program_directive('[?xml-stylesheet href=a]\n[m]'.bytes())
	// Negative: an UNregistered `[?…]` head is not a directive.
	assert !cx.source_carries_program_directive('[?nosuchthing 1]'.bytes())
	// Negative: opaque spans are skipped, so a directive named in prose,
	// in a line comment, in a block comment, or inside raw text is not shape.
	assert !cx.source_carries_program_directive("[doc 'see [?let]']".bytes())
	assert !cx.source_carries_program_directive('# see [?let]\n[m]'.bytes())
	assert !cx.source_carries_program_directive('[;see [?let] first]\n[m]'.bytes())
	assert !cx.source_carries_program_directive('[doc [# [?let] #]]'.bytes())
	// And the shielding does not swallow a REAL directive that follows the
	// opaque span — the scan resumes at the span end, it does not give up.
	assert cx.source_carries_program_directive('# see [?let]\n[?def f () 1]'.bytes())
	assert cx.source_carries_program_directive("[doc 'see [?let]']\n[?def f () 1]".bytes())
}

// ── #1055: the startup budget is a PIN, not a hope ────────────────────────
//
// The class of defect: work that boot does unconditionally, for a capability
// the invocation never asks for. #1055's instance was two `const`s in the RE2
// layer whose initialisers were function CALLS — so V emitted them into
// `_vinit` and every process, `cx --version` included, walked \p{L}'s ~560
// codepoint intervals and rendered them to \x{...} class items before the
// dispatcher ever saw argv. Nothing about that cost is visible in a normal
// test: every assertion still passed, only slower. It surfaced as an
// unrelated lane going red — net_udp_read_deadline_test's delivery case,
// where the child has to bind its socket before the parent's send.
//
// So the budget is pinned here, on the cheapest invocation the binary has.
// `--version` reaches no evaluator, opens no store, resolves no module: what
// it measures is process start plus whatever `_vinit` decided to do. Any
// future eager init lands on this assertion instead of on a distant lane.
//
// The bound is deliberately loose. Measured warm on an M-series laptop:
// v0.16.0 released 53 ms, this tree 20 ms, and the regressed artifact that
// filed #1055 556 ms. 300 ms sits an order of magnitude above the real cost
// and still an order of magnitude below the regression, so a loaded CI box
// cannot flake it and a returning eager-init cannot hide under it.
const cx_startup_budget_ms = 300

// Best-of-N, not mean: scheduler noise can only ADD time, so the minimum is
// the closest estimate of the binary's own cost and the least flakeable
// statistic. A real regression raises the floor and reds every sample.
fn test_version_startup_stays_within_budget() {
	bin := testenv.cx_bin()
	// Warm the page cache and any first-run code-signature check — the pin is
	// on steady-state startup, which is what every gate subprocess pays.
	for _ in 0 .. 2 {
		os.execute('${bin} --version')
	}
	mut best_ms := i64(1 << 40)
	for _ in 0 .. 5 {
		t0 := time.now()
		r := os.execute('${bin} --version')
		ms := time.since(t0).milliseconds()
		assert r.exit_code == 0, 'cx --version failed: ${r.output}'
		assert r.output.contains('cx v'), 'cx --version printed no version line: ${r.output}'
		if ms < best_ms {
			best_ms = ms
		}
	}
	assert best_ms <= cx_startup_budget_ms, 'cx --version startup regressed: best of 5 warm runs was ${best_ms} ms, budget ${cx_startup_budget_ms} ms. Something now runs at boot that the invocation did not ask for — check for a const whose initialiser is a function call (it lands in _vinit), or an eager load added to module init. See #1055.'
}

// The same budget on a TINY program: `--version` short-circuits before the
// evaluator, so on its own it cannot catch an eager init that hangs off the
// eval path. One trivial script covers the rest of the pre-dispatch walk.
// Its own work is a single literal, so anything above the budget is boot.
fn test_tiny_script_startup_stays_within_budget() {
	bin := testenv.cx_bin()
	f := os.join_path(os.temp_dir(), 'cx_startup_budget_${os.getpid()}.cx')
	os.write_file(f, '[?let [= \$x 1] \$x]\n') or {
		assert false, 'write ${f}: ${err}'
		return
	}
	defer {
		os.rm(f) or {}
	}
	for _ in 0 .. 2 {
		os.execute('${bin} ${f}')
	}
	mut best_ms := i64(1 << 40)
	for _ in 0 .. 5 {
		t0 := time.now()
		r := os.execute('${bin} ${f}')
		ms := time.since(t0).milliseconds()
		assert r.exit_code == 0, 'tiny script failed: ${r.output}'
		if ms < best_ms {
			best_ms = ms
		}
	}
	assert best_ms <= cx_startup_budget_ms, 'tiny-script startup regressed: best of 5 warm runs was ${best_ms} ms, budget ${cx_startup_budget_ms} ms. See #1055.'
}
